import type {
  CanvasNodeInteractionState,
  CanvasNodeVisualStatusTone,
} from "@workspace/ui/components/canvas-node/canvas-node";
import type { ReactNode } from "react";

export type DatabaseEngineKey =
  | "mongodb"
  | "mysql"
  | "postgresql"
  | "redis"
  | (string & {});

export type DatabaseNodeMetricKey = "cpu" | "memory" | "storage";

export type DatabaseNodeMetricValue = number | string;

export type DatabaseNodeStatusTone =
  | "available"
  | "binding"
  | "bound"
  | "complete"
  | "creating"
  | "degraded"
  | "deleting"
  | "error"
  | "failed"
  | "inaccessible"
  | "not-configured"
  | "paused"
  | "pending"
  | "progressing"
  | "ready"
  | "reconciling"
  | "restarting"
  | "running"
  | "shutdown"
  | "starting"
  | "stopped"
  | "stopping"
  | "succeeded"
  | "suspended"
  | "unconfigured"
  | "unavailable"
  | "unhealthy"
  | "unknown"
  | "updating"
  | (string & {});

export interface DatabaseNodeStatus {
  label: string;
  tone?: DatabaseNodeStatusTone;
  visualTone?: CanvasNodeVisualStatusTone;
}

export interface DatabaseNodeStates {
  deletionTimestamp?: string;
  displayEngine: string;
  engineKey?: DatabaseEngineKey;
  formattedVersion?: string;
  iconUrl?: string;
  metricCapacities?: Partial<Record<DatabaseNodeMetricKey, string>>;
  metrics?: Partial<Record<DatabaseNodeMetricKey, DatabaseNodeMetricValue>>;
  mountPath?: string;
  name: string;
  status?: DatabaseNodeStatus;
}

interface DatabaseNodeConnectionBase {
  displayValue?: string;
  id?: string;
  label: string;
  value?: string;
}

export interface DatabaseNodePrivateConnection
  extends DatabaseNodeConnectionBase {
  kind: "private";
  unavailableMessage?: string;
}

export interface DatabaseNodePublicConnection
  extends DatabaseNodeConnectionBase {
  kind: "public";
  provisioningMessage?: string;
  publicAccess: {
    enabled: boolean;
    loading?: boolean;
  };
}

export type DatabaseNodeConnection =
  | DatabaseNodePrivateConnection
  | DatabaseNodePublicConnection;

export type DatabaseNodeConnectionKey = string;

export type DatabaseNodeCopyConnectionHandler = (
  connection: DatabaseNodeConnection,
  index: number,
  /** The row's on-screen value while its reveal is active — copy reuses it instead of fetching (ADR-0055). */
  activeRevealValue?: string
) => Promise<void> | void;

export type DatabaseNodeRevealConnectionHandler = (
  connection: DatabaseNodeConnection,
  index: number
) => Promise<void> | void;

/** The single revealed connection row (ADR-0055: one at a time). */
export interface DatabaseNodeRevealedConnection {
  key: DatabaseNodeConnectionKey;
  value: string;
}

export type DatabaseNodeTogglePublicConnectionHandler = (
  connection: DatabaseNodePublicConnection,
  index: number,
  nextEnabled: boolean
) => Promise<void> | void;

export type DatabaseNodeQuickActionKey =
  | "dbAccess"
  | "logs"
  | "metrics"
  | "terminal";

export type DatabaseNodeLifecycleActionKey =
  | "delete"
  | "restart"
  | "start"
  | "stop";

export interface DatabaseNodeAction {
  disabled?: boolean;
  disabledReason?: string;
  loading?: boolean;
  onClick?: () => Promise<void> | void;
}

export type DatabaseNodeQuickActions = Partial<
  Record<DatabaseNodeQuickActionKey, DatabaseNodeAction>
>;

export type DatabaseNodeLifecycleActions = Partial<
  Record<DatabaseNodeLifecycleActionKey, DatabaseNodeAction>
>;

export interface DatabaseNodeActions {
  copyConnection?: DatabaseNodeCopyConnectionHandler;
  lifecycleActions?: DatabaseNodeLifecycleActions;
  quickActions?: DatabaseNodeQuickActions;
  /** Toggles the reveal of one connection row; absent when no resolver backs the canvas. */
  revealConnection?: DatabaseNodeRevealConnectionHandler;
  togglePublicConnection?: DatabaseNodeTogglePublicConnectionHandler;
  /** User-facing reason shown when the public access toggle is unavailable. */
  togglePublicConnectionDisabledReason?: string;
}

export interface DatabaseNodeMeta {
  copiedFeedbackMs?: number;
}

export interface DatabaseNodeState {
  connections?: DatabaseNodeConnection[];
  copiedConnectionKey?: DatabaseNodeConnectionKey | null;
  revealedConnection?: DatabaseNodeRevealedConnection | null;
  states: DatabaseNodeStates;
}

export interface DatabaseNodeContextValue {
  actions: DatabaseNodeActions;
  meta: DatabaseNodeMeta;
  state: DatabaseNodeState;
}

export interface DatabaseNodeProviderProps {
  children?: ReactNode;
  value: DatabaseNodeContextValue;
}

export interface DatabaseNodeRootProps {
  children?: ReactNode;
  connections?: DatabaseNodeConnection[];
  copiedConnectionKey?: DatabaseNodeConnectionKey | null;
  copiedFeedbackMs?: number;
  defaultExpanded?: boolean;
  expanded?: boolean;
  interaction?: CanvasNodeInteractionState;
  lifecycleActions?: DatabaseNodeLifecycleActions;
  onCopyConnection?: DatabaseNodeCopyConnectionHandler;
  onExpandedChange?: (expanded: boolean) => void;
  onRevealConnection?: DatabaseNodeRevealConnectionHandler;
  onTogglePublicConnection?: DatabaseNodeTogglePublicConnectionHandler;
  quickActions?: DatabaseNodeQuickActions;
  revealedConnection?: DatabaseNodeRevealedConnection | null;
  states: DatabaseNodeStates;
  togglePublicConnectionDisabledReason?: string;
}

import {
  CANVAS_NODE_BUSY_TONES,
  CANVAS_NODE_FAILED_TONES,
  CANVAS_NODE_RUNNING_TONES,
  CANVAS_NODE_STOPPED_TONES,
  type CanvasNodeActionAvailability,
  type CanvasNodeLifecycleAvailability,
  canvasNodeLifecycleAvailability,
  normalizeCanvasNodeStatusTone,
} from "@workspace/ui/components/canvas-node/canvas-node.availability";

import type {
  DatabaseNodeQuickActionKey,
  DatabaseNodeStatusTone,
} from "./database-node.types";

const REASON_NOUN = "Database";

/** Lifecycle menu entries resolved from the database status tone. */
export function databaseNodeLifecycleAvailability(
  tone: DatabaseNodeStatusTone | string | undefined
): CanvasNodeLifecycleAvailability {
  return canvasNodeLifecycleAvailability(tone, REASON_NOUN);
}

function liveSessionGate(disabledReason: string) {
  const entry: CanvasNodeActionAvailability = { disabledReason, present: true };
  return { dbAccess: entry, terminal: entry };
}

/**
 * State gates for database quick actions. Terminal and DB Access sessions are
 * accepted by the platform only while the database reports a running phase, so
 * both mirror that gate; failed databases are rejected as well. Logs and
 * metrics keep their historical value in every state and are never gated here.
 */
export function databaseNodeQuickActionAvailability(
  tone: DatabaseNodeStatusTone | string | undefined
): Partial<Record<DatabaseNodeQuickActionKey, CanvasNodeActionAvailability>> {
  const normalized = normalizeCanvasNodeStatusTone(tone);

  if (normalized != null && CANVAS_NODE_RUNNING_TONES.has(normalized)) {
    return {};
  }
  if (normalized != null && CANVAS_NODE_STOPPED_TONES.has(normalized)) {
    return liveSessionGate(`${REASON_NOUN} is not running.`);
  }
  if (normalized != null && CANVAS_NODE_FAILED_TONES.has(normalized)) {
    return liveSessionGate(`${REASON_NOUN} is not ready.`);
  }
  if (normalized === "starting") {
    return liveSessionGate(`${REASON_NOUN} is starting.`);
  }
  if (normalized === "stopping") {
    return liveSessionGate(`${REASON_NOUN} is stopping.`);
  }
  if (normalized === "restarting") {
    return liveSessionGate(`${REASON_NOUN} is restarting.`);
  }
  if (normalized === "deleting") {
    return liveSessionGate(`${REASON_NOUN} is being deleted.`);
  }
  if (normalized != null && CANVAS_NODE_BUSY_TONES.has(normalized)) {
    return liveSessionGate(`${REASON_NOUN} is busy right now.`);
  }
  return liveSessionGate(`${REASON_NOUN} state is unknown.`);
}

"use client";

import { createContext, use } from "react";

import type { DatabaseNodeContextValue } from "./database-node.types";

export const DatabaseNodeContext =
  createContext<DatabaseNodeContextValue | null>(null);

export function useDatabaseNode(): DatabaseNodeContextValue {
  const value = use(DatabaseNodeContext);

  if (!value) {
    throw new Error(
      "DatabaseNode: compound components must be used within DatabaseNode.Root"
    );
  }

  return value;
}

"use client";

import { DatabaseNodeContext } from "./database-node.context";
import type { DatabaseNodeProviderProps } from "./database-node.types";

export function DatabaseNodeProvider({
  children,
  value,
}: DatabaseNodeProviderProps) {
  return <DatabaseNodeContext value={value}>{children}</DatabaseNodeContext>;
}

"use client";

import {
  CANVAS_NODE_DEFAULT_COPIED_FEEDBACK_MS,
  CanvasNodeCopyFeedbackScope,
} from "@workspace/ui/components/canvas-node/canvas-node.copyable-row";
import { CanvasNodeRoot } from "@workspace/ui/components/canvas-node/canvas-node.root";

import { DatabaseNodeProvider } from "./database-node.provider";
import type {
  DatabaseNodeConnection,
  DatabaseNodeConnectionKey,
  DatabaseNodeContextValue,
  DatabaseNodeRootProps,
} from "./database-node.types";

export function getDatabaseNodeConnectionKey(
  connection: DatabaseNodeConnection,
  index: number
) {
  return connection.id ?? String(index);
}

export function canCopyDatabaseNodeConnection(
  connection: DatabaseNodeConnection
) {
  if (!connection.value) {
    return false;
  }

  if (connection.kind === "public" && !connection.publicAccess.enabled) {
    return false;
  }

  return true;
}

export function DatabaseNodeRoot({
  children,
  connections,
  copiedConnectionKey,
  copiedFeedbackMs = CANVAS_NODE_DEFAULT_COPIED_FEEDBACK_MS,
  defaultExpanded,
  expanded,
  interaction,
  lifecycleActions,
  onCopyConnection,
  onExpandedChange,
  onRevealConnection,
  onTogglePublicConnection,
  quickActions,
  revealedConnection,
  states,
  togglePublicConnectionDisabledReason,
}: DatabaseNodeRootProps) {
  return (
    <CanvasNodeRoot
      defaultExpanded={defaultExpanded}
      expanded={expanded}
      interaction={interaction}
      onExpandedChange={onExpandedChange}
    >
      <CanvasNodeCopyFeedbackScope
        copiedFeedbackMs={copiedFeedbackMs}
        copiedKey={copiedConnectionKey}
      >
        {({ copiedKey }) => {
          const value: DatabaseNodeContextValue = {
            actions: {
              copyConnection: onCopyConnection,
              lifecycleActions,
              quickActions,
              revealConnection: onRevealConnection,
              togglePublicConnection: onTogglePublicConnection,
              togglePublicConnectionDisabledReason,
            },
            meta: {
              copiedFeedbackMs,
            },
            state: {
              connections,
              copiedConnectionKey:
                copiedKey as DatabaseNodeConnectionKey | null,
              revealedConnection,
              states,
            },
          };

          return (
            <DatabaseNodeProvider value={value}>
              {children}
            </DatabaseNodeProvider>
          );
        }}
      </CanvasNodeCopyFeedbackScope>
    </CanvasNodeRoot>
  );
}

import type {
  CanvasNodeStatus,
  CanvasNodeVisualStatusTone,
} from "@workspace/ui/components/canvas-node/canvas-node";

import type { DatabaseNodeStatus } from "./database-node.types";

const POSITIVE_STATUSES = new Set([
  "accessible",
  "available",
  "bound",
  "complete",
  "ready",
  "running",
  "succeeded",
]);

const PROGRESS_STATUSES = new Set([
  "binding",
  "creating",
  "pending",
  "progressing",
  "reconciling",
  "restarting",
  "starting",
  "updating",
]);

const WARNING_STATUSES = new Set(["degraded", "deleting", "stopping"]);

const NEGATIVE_STATUSES = new Set([
  "error",
  "failed",
  "inaccessible",
  "unavailable",
  "unhealthy",
]);

const NEUTRAL_STATUSES = new Set([
  "not-configured",
  "paused",
  "shutdown",
  "stopped",
  "suspended",
  "unconfigured",
  "unknown",
]);

function normalizeDatabaseStatusTone(input: string | undefined) {
  return input
    ?.trim()
    .toLowerCase()
    .replace(/[\s_]+/g, "-");
}

export function resolveDatabaseNodeVisualTone(
  status: DatabaseNodeStatus | undefined
): CanvasNodeVisualStatusTone {
  if (status?.visualTone) {
    return status.visualTone;
  }

  const tone = normalizeDatabaseStatusTone(status?.tone ?? status?.label);

  if (tone && POSITIVE_STATUSES.has(tone)) {
    return "positive";
  }

  if (tone && PROGRESS_STATUSES.has(tone)) {
    return "progress";
  }

  if (tone && WARNING_STATUSES.has(tone)) {
    return "warning";
  }

  if (tone && NEGATIVE_STATUSES.has(tone)) {
    return "negative";
  }

  if (tone && NEUTRAL_STATUSES.has(tone)) {
    return "neutral";
  }

  return "neutral";
}

export function resolveDatabaseNodeStatus(
  status: DatabaseNodeStatus | undefined
): CanvasNodeStatus {
  return {
    label: status?.label?.trim() || "Unknown",
    visualTone: resolveDatabaseNodeVisualTone(status),
  };
}

"use client";

import { AppIconButton } from "@workspace/ui/components/app-icon-button";
import {
  CanvasNodeCopyableRow,
  CanvasNodeCopyableRowControl,
  useCanvasNodeCopyableRow,
} from "@workspace/ui/components/canvas-node/canvas-node.copyable-row";
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@workspace/ui/components/tooltip";
import { useBusyAction } from "@workspace/ui/hooks/use-busy-action";
import { cn } from "@workspace/ui/lib/utils";
import { Check, Copy, Eye, EyeClosed } from "lucide-react";
import type { ReactNode } from "react";

import { DATABASE_CONNECTION_MASK } from "./database-node.mask";
import type { DatabaseNodeConnection } from "./database-node.types";

export type DatabaseConnectionRowVariant = "node" | "settings";

export interface DatabaseConnectionRowProps {
  className?: string;
  connection: DatabaseNodeConnection;
  /** Display label; defaults to the connection's own label. */
  label?: string;
  onCopy?: () => Promise<void> | void;
  /** Enables the eye; absent when no resolver backs the surface. */
  onToggleReveal?: () => Promise<void> | void;
  /** Overrides the connection's public-access state (e.g. a settings draft). */
  publicAccessEnabled?: boolean;
  /** Label-line control on public rows; never participates in copy. */
  publicSwitch?: ReactNode;
  revealedValue?: string;
  rowKey: string;
  variant?: DatabaseConnectionRowVariant;
}

interface DatabaseConnectionRowStyles {
  label: string;
  row: string;
  rowWithoutValue: string;
  rowWithValue: string;
  valueLine: string;
  valueText: string;
}

const ROW_VARIANT_CLASSES: Record<
  DatabaseConnectionRowVariant,
  DatabaseConnectionRowStyles
> = {
  node: {
    label: "text-xs leading-4",
    row: "bg-zinc-950/20 p-2.5",
    rowWithoutValue: "min-h-11",
    rowWithValue: "min-h-18",
    valueLine: "h-7 text-xs leading-4",
    valueText: "text-zinc-50",
  },
  settings: {
    label: "text-sm leading-5",
    row: "bg-white/5 p-4 shadow-sm",
    rowWithoutValue: "min-h-11",
    rowWithValue: "min-h-20",
    valueLine: "h-8 text-sm leading-5",
    valueText: "text-foreground",
  },
};

type DatabaseConnectionRowValueKind =
  | { kind: "message"; text: string }
  | { kind: "secret" }
  | null;

function databaseConnectionRowValueKind(
  connection: DatabaseNodeConnection,
  publicAccessEnabled: boolean
): DatabaseConnectionRowValueKind {
  if (connection.kind === "public" && !publicAccessEnabled) {
    return null;
  }
  if (connection.value) {
    return { kind: "secret" };
  }
  if (connection.kind === "public") {
    return {
      kind: "message",
      text: connection.provisioningMessage ?? "Provisioning connection string",
    };
  }
  return {
    kind: "message",
    text: connection.unavailableMessage ?? "Connection unavailable",
  };
}

/**
 * The one DB connection row anatomy shared by the canvas DB node and DB
 * Settings (ADR-0055): label plus optional public switch on the top line;
 * fixed-width mask, eye, and copy on the value line. The eye swaps the
 * revealed DSN into the row in place, hovering the revealed value reads the
 * full DSN in a tooltip, and copy (whole-row click or the button) runs the
 * injected on-demand fetch — the row never renders the DB Connection
 * Template.
 */
export function DatabaseConnectionRow({
  className,
  connection,
  label = connection.label,
  onCopy,
  onToggleReveal,
  publicAccessEnabled,
  publicSwitch,
  revealedValue,
  rowKey,
  variant = "node",
}: DatabaseConnectionRowProps) {
  const styles = ROW_VARIANT_CLASSES[variant];
  const publicEnabled =
    connection.kind === "public"
      ? (publicAccessEnabled ?? connection.publicAccess.enabled)
      : true;
  const valueKind = databaseConnectionRowValueKind(connection, publicEnabled);
  const copyable = valueKind?.kind === "secret";

  return (
    <CanvasNodeCopyableRow
      className={cn(
        "database-connection-row relative flex min-w-0 flex-col gap-2 rounded-lg transition-colors",
        styles.row,
        valueKind ? styles.rowWithValue : styles.rowWithoutValue,
        className
      )}
      copyAriaLabel={`Copy ${label}`}
      copyable={copyable}
      copyValue={connection.value}
      data-slot="database-connection-row"
      onCopy={onCopy ? () => onCopy() : undefined}
      rowKey={rowKey}
      // Suppress the hit-area's native tooltip: it would fall back to the
      // copy value, and the DB Connection Template must never reach the
      // screen (ADR-0055). The revealed-value tooltip is the reading surface.
      title=""
    >
      {({ copied, copyable: rowCopyable }) => (
        <>
          <div
            className={cn(
              "relative z-10 flex min-w-0 items-center justify-between gap-2",
              rowCopyable ? "pointer-events-none" : "pointer-events-auto"
            )}
          >
            <span
              className={cn(
                "min-w-0 truncate font-normal text-muted-foreground",
                styles.label
              )}
            >
              {label}
            </span>
            {publicSwitch ? (
              <CanvasNodeCopyableRowControl className="pointer-events-auto relative z-20 flex shrink-0 items-center">
                {publicSwitch}
              </CanvasNodeCopyableRowControl>
            ) : null}
          </div>
          {valueKind == null ? null : (
            <DatabaseConnectionRowValueLine
              copied={copied}
              label={label}
              onToggleReveal={onToggleReveal}
              revealedValue={revealedValue}
              rowCopyable={rowCopyable}
              styles={styles}
              valueKind={valueKind}
            />
          )}
        </>
      )}
    </CanvasNodeCopyableRow>
  );
}

function DatabaseConnectionRowValueLine({
  copied,
  label,
  onToggleReveal,
  revealedValue,
  rowCopyable,
  styles,
  valueKind,
}: {
  copied: boolean;
  label: string;
  onToggleReveal?: () => Promise<void> | void;
  revealedValue?: string;
  rowCopyable: boolean;
  styles: DatabaseConnectionRowStyles;
  valueKind: NonNullable<DatabaseConnectionRowValueKind>;
}) {
  const revealed = revealedValue !== undefined;
  const { busy: copyBusy, copyRow } = useCanvasNodeCopyableRow();
  const { busy: revealBusy, trigger: handleRevealClick } = useBusyAction(() =>
    onToggleReveal?.()
  );
  const handleCopyClick = () => {
    copyRow().catch(() => undefined);
  };

  return (
    <div
      className={cn(
        "relative z-10 flex min-w-0 items-center justify-between gap-2 py-1.5 text-left font-normal",
        styles.valueLine,
        rowCopyable
          ? cn("pointer-events-none", styles.valueText)
          : "pointer-events-auto text-muted-foreground"
      )}
      data-copied={copied ? "true" : undefined}
      data-revealed={revealed ? "true" : undefined}
      data-slot="database-connection-value"
    >
      {valueKind.kind === "secret" ? (
        <>
          <DatabaseConnectionRowSecretValue
            onCopyClick={handleCopyClick}
            revealedValue={revealedValue}
          />
          <CanvasNodeCopyableRowControl
            className={cn(
              "pointer-events-auto relative z-20 -mr-1.5 flex shrink-0 items-center gap-0.5 transition-opacity",
              // Progressive disclosure: controls surface on row hover/focus.
              // Pinned while revealed (the closed eye is the only early-hide
              // affordance for the on-screen DSN), during copy feedback, and
              // while either control's on-demand fetch is in flight.
              revealed || copied || revealBusy || copyBusy
                ? "opacity-100"
                : "opacity-0 group-focus-within/copyable-row:opacity-100 group-hover/copyable-row:opacity-100"
            )}
          >
            {onToggleReveal ? (
              <AppIconButton
                aria-label={`${revealed ? "Hide" : "Reveal"} ${label}`}
                aria-pressed={revealed}
                busy={revealBusy}
                className="text-muted-foreground hover:text-foreground"
                data-slot="database-connection-reveal-button"
                onClick={handleRevealClick}
                size="sm"
                type="button"
                variant="quiet"
              >
                {revealed ? (
                  <EyeClosed aria-hidden className="size-4" />
                ) : (
                  <Eye aria-hidden className="size-4" />
                )}
              </AppIconButton>
            ) : null}
            <AppIconButton
              aria-label={`${copied ? "Copied" : "Copy"} ${label}`}
              busy={copyBusy}
              className={cn(
                "text-muted-foreground hover:text-foreground",
                copied && "text-foreground"
              )}
              data-slot="database-connection-copy-button"
              onClick={handleCopyClick}
              size="sm"
              type="button"
              variant="quiet"
            >
              {copied ? (
                <Check aria-hidden className="size-4" />
              ) : (
                <Copy aria-hidden className="size-4" />
              )}
            </AppIconButton>
          </CanvasNodeCopyableRowControl>
        </>
      ) : (
        <span className="min-w-0 truncate" title={valueKind.text}>
          {valueKind.text}
        </span>
      )}
    </div>
  );
}

function DatabaseConnectionRowSecretValue({
  onCopyClick,
  revealedValue,
}: {
  onCopyClick: () => void;
  revealedValue?: string;
}) {
  if (revealedValue === undefined) {
    return (
      <span aria-hidden className="min-w-0 flex-1 truncate">
        {DATABASE_CONNECTION_MASK}
      </span>
    );
  }

  // The revealed value takes pointer events for the tooltip, so it is a real
  // button forwarding clicks to keep whole-row copy true; keyboard copy stays
  // on the row hit-area and the explicit copy button.
  return (
    <Tooltip>
      <TooltipTrigger
        className="nodrag nopan pointer-events-auto min-w-0 flex-1 cursor-pointer truncate text-left"
        onClick={onCopyClick}
        tabIndex={-1}
        type="button"
      >
        {revealedValue}
      </TooltipTrigger>
      <TooltipContent>{revealedValue}</TooltipContent>
    </Tooltip>
  );
}

"use client";

import {
  CanvasNode,
  type CanvasNodeMetricListItem,
} from "@workspace/ui/components/canvas-node/canvas-node";
import { canvasNodeActionWithAvailability } from "@workspace/ui/components/canvas-node/canvas-node.availability";
import { DatabaseEngineIcon } from "@workspace/ui/components/database-engine-icon";
import { Switch } from "@workspace/ui/components/switch";
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@workspace/ui/components/tooltip";
import { cn } from "@workspace/ui/lib/utils";
import {
  Activity,
  Cpu,
  FileText,
  HardDrive,
  MemoryStick,
  Pause,
  Play,
  RotateCcw,
  SquareTerminal,
  TableProperties,
  Trash2,
  TriangleAlert,
} from "lucide-react";
import type { ComponentType, ReactNode, SVGProps } from "react";

import {
  databaseNodeLifecycleAvailability,
  databaseNodeQuickActionAvailability,
} from "./database-node.availability";
import { DatabaseConnectionRow } from "./database-node.connection-row";
import { useDatabaseNode } from "./database-node.context";
import { getDatabaseNodeConnectionKey } from "./database-node.root";
import { resolveDatabaseNodeStatus } from "./database-node.status";
import type {
  DatabaseNodeConnection,
  DatabaseNodeLifecycleActionKey,
  DatabaseNodeMetricKey,
  DatabaseNodePublicConnection,
  DatabaseNodeQuickActionKey,
  DatabaseNodeStates,
} from "./database-node.types";

const METRIC_ITEMS = [
  { icon: Cpu, key: "cpu", label: "CPU" },
  { icon: MemoryStick, key: "memory", label: "Memory" },
  { icon: HardDrive, key: "storage", label: "Storage" },
] as const satisfies readonly CanvasNodeMetricListItem<DatabaseNodeMetricKey>[];

const QUICK_ACTION_ITEMS = [
  { icon: Activity, key: "metrics", label: "Open metrics", tooltip: "Metrics" },
  {
    icon: SquareTerminal,
    key: "terminal",
    label: "Open terminal",
    tooltip: "Terminal",
  },
  { icon: FileText, key: "logs", label: "Open logs", tooltip: "Logs" },
  {
    icon: TableProperties,
    key: "dbAccess",
    label: "Open database access",
    tooltip: "Database access",
  },
] as const satisfies readonly {
  icon: ComponentType<SVGProps<SVGSVGElement>>;
  key: DatabaseNodeQuickActionKey;
  label: string;
  tooltip: string;
}[];

interface LifecycleActionItem {
  icon: ComponentType<SVGProps<SVGSVGElement>>;
  key: DatabaseNodeLifecycleActionKey;
  label: string;
  tone?: "destructive" | "info" | "muted" | "success";
